            } elsif ($arg =~ /^[a-zA-Z0-9_-]+$/) {
                # Assume it's a target name
                push @targets, $self->target_params(name => $arg);
            } else {
                # Unrecognized argument
                push @names, $arg;
            }
        }
    }

    if ($target_name) {
        push @targets, $self->target_params(name => $target_name);
    } else {
        # No target specified, use default target
        my $default_target = $self->default_target;
        push @targets, $default_target;
        @changes = grep { $_ =~ /^[a-zA-Z0-9_-]+$/ } @changes;
    }

    return @names, \@targets, \@changes;
}
