    my ( $class, $config, $opt ) = @_;

    # Default parameters
    my %params = (
        change_name       => undef,
        note              => undef,
        requires          => [],
        conflicts         => [],
        all               => 0,
        template_name     => undef,
        template_directory => undef,
        with_scripts      => {},
    );

    # Set change_name if provided
    if (exists $opt->{change}) {
        $params{change_name} = $opt->{change};
    }

    # Set note if provided
    if (exists $opt->{note}) {
        $params{note} = $opt->{note};
    }

    # Set requires if provided
    if (exists $opt->{requires}) {
        $params{requires} = ref $opt->{requires} ? $opt->{requires} : [$opt->{requires}];
    }

    # Set conflicts if provided
    if (exists $opt->{conflicts}) {
        $params{conflicts} = ref $opt->{conflicts} ? $opt->{conflicts} : [$opt->{conflicts}];
    }

    # Set all if provided
    if (exists $opt->{all}) {
        $params{all} = $opt->{all};
    }

    # Set template_name if provided
    if (exists $opt->{template}) {
        $params{template_name} = $opt->{template};
    }

    # Set template_directory if provided
    if (exists $opt->{template_dir}) {
        $params{template_directory} = $opt->{template_dir};
    } else {
        # Determine the default template directory
        my $etc_path = `sqitch --etc-path`;
        chomp($etc_path);
        $params{template_directory} = "$etc_path/sqitch/templates";
    }

    # Set with_scripts if provided
    if (exists $opt->{scripts}) {
        $params{with_scripts} = ref $opt->{scripts} ? $opt->{scripts} : { map { $_ => 1 } split /[,]/, $opt->{scripts} };
    }

    return \%params;
}
