        hurl 'E_MISSING_ACTION', __("Action is required") unless $opt->{action};
    }

    # Create the configuration parameters hash
    my $params = {
        sqitch => $config->{sqitch},
        file   => $config->{file},
        action => $opt->{action},
        context => $opt->{context} // 'local',
        type    => $opt->{type},
    };

    # Additional processing based on the action
    if ( $opt->{action} eq 'set' || $opt->{action} eq 'add' || $opt->{action} eq 'replace-all' || $opt->{action} eq 'unset' || $opt->{action} eq 'unset-all' ) {
        if ( !defined $opt->{property} ) {
            hurl 'E_MISSING_PROPERTY', __("Property is required for action %s", $opt->{action}) unless $opt->{property};
        }
        if ( defined $opt->{value} ) {
            $params->{property} = $opt->{property};
            $params->{value}    = $opt->{value};
            $params->{regex}    = $opt->{regex};
        }
    }

    return $params;
}
