sub _copy {
    my ( $self, $src, $dest, $orig ) = @_;
    $orig ||= $src;
    if (!-e $orig) {
        $self->debug(__x(
            'Skipped {dest}: {src} does not exist',
            dest => $dest,
            src  => $orig,
        ));
        return;
    }

    # Create the directory for the file, if it does not exist.
    $self->_mkpath($dest->dir->stringify);

    # Stringify to work around bug in File::Copy warning on 5.10.0.
