    my $plan = $self->plan;
    my $change = $state->{change};

    unless (defined $plan->{$change}) {
        hurl(sprintf(__("Change '%s' not found in plan."), $change));
    }

    my $current_state = $state->{state};
    my $plan_state = $plan->{$change}->{state};

    if ($current_state eq $plan_state) {
        print __("The plan and the database are in sync.\n");
    } else {
        print __("The plan and the database are out of sync.\n");
    }
}

