sub format {
    my ($self, $format, $item) = @_;

    # Initialize the formatter with the default settings
    my $formatter = String::Formatter->new(
        default_format => $format,
        config         => {
            abbrev        => $self->{abbrev},
            date_format   => $self->{date_format},
            color         => $self->{color},
            formatter     => $self->{formatter},
        },
    );

    # Create a hash reference with the item data
    my $item_ref = {
        event        => $item->{event},
        project      => $item->{project},
        change_id    => $item->{change_id},
        change       => $item->{change},
        note         => $item->{note},
        tags         => $item->{tags},
        requires     => $item->{requires},
        conflicts    => $item->{conflicts},
        committed_at => $item->{committed_at},
        committer_name => $item->{committer_name},
        committer_email => $item->{committer_email},
