sub parse {
    my ( $class, $string ) = @_;
    my %params;

    # Check the basic format of the dependency string
    if ($string =~ /^([\w:]+):([\w@]+)(?:@(\w+))?$/) {
        %params = (
            project => $1,
            change  => $2,
            tag     => $3,
        );

        # If the change contains an '@', it should be split into change and tag
        if ($params{change} && $params{change} =~ /@/) {
            ($params{change}, $params{tag}) = split /@/, $params{change}, 2;
        }

        # Check if the dependency is a conflict
        $params{conflicts} = 1 if $string =~ /^!/;

        return \%params;
    }

    # Return undef if the string does not match the expected format
    return undef;
}

